import inspect


class ModelRetry(Exception):
    pass


class UnexpectedModelBehavior(Exception):
    pass


class RunContext:
    def __init__(self, deps, messages, retry):
        self.deps = deps
        self.messages = messages
        self.retry = retry


class Agent:
    def __init__(self, instructions="", output_type=None, retries=1):
        self.instructions = instructions
        self.output_type = output_type
        self.retries = retries
        self.tools = {}

    def tool(self, fn):
        self.tools[fn.__name__] = (fn, True)
        return fn

    def tool_plain(self, fn):
        self.tools[fn.__name__] = (fn, False)
        return fn

    def output_validator(self, fn):
        self.validators = getattr(self, "validators", [])
        self.validators.append(fn)
        return fn

    def catalog(self):
        entries = []
        for name, (fn, takes_ctx) in self.tools.items():
            parameters = {}
            signature = inspect.signature(fn)
            for index, parameter in enumerate(signature.parameters.values()):
                if takes_ctx and index == 0:
                    continue
                parameters[parameter.name] = (
                    parameter.annotation
                    if parameter.annotation is not inspect.Parameter.empty else object)
            doc = inspect.getdoc(fn) or ""
            entries.append({
                "name": name,
                "description": doc.splitlines()[0].strip() if doc else "",
                "parameters": parameters,
            })
        return entries

    def _check_args(self, name, args):
        fn, takes_ctx = self.tools[name]
        declared = self.catalog()
        wanted = next(e["parameters"] for e in declared if e["name"] == name)
        missing = [p for p in wanted if p not in args]
        if missing:
            raise ModelRetry(f"{name} is missing argument(s): {', '.join(missing)}")
        extra = [a for a in args if a not in wanted]
        if extra:
            raise ModelRetry(f"{name} got unexpected argument(s): {', '.join(extra)}")
        for parameter, expected in wanted.items():
            if expected is object or not isinstance(expected, type):
                continue
            value = args[parameter]
            if expected is float and isinstance(value, int) and not isinstance(value, bool):
                continue
            if not isinstance(value, expected):
                raise ModelRetry(
                    f"{name}.{parameter} must be {expected.__name__}, "
                    f"got {type(value).__name__}")

    def run(self, prompt, model, deps=None, max_turns=10):
        messages = [{"role": "user", "content": prompt}]
        failures = 0
        model_calls = 0
        tool_calls = 0
        for _ in range(max_turns):
            context = RunContext(deps, messages, failures)
            response = model(list(messages), self.catalog())
            model_calls += 1
            if "tool" in response:
                name = response["tool"]
                args = dict(response.get("args") or {})
                try:
                    if name not in self.tools:
                        raise ModelRetry(f"unknown tool {name!r}")
                    self._check_args(name, args)
                    fn, takes_ctx = self.tools[name]
                    result = fn(context, **args) if takes_ctx else fn(**args)
                except ModelRetry as retry:
                    failures += 1
                    if failures > self.retries:
                        raise UnexpectedModelBehavior(str(retry))
                    messages.append({"role": "retry", "content": str(retry)})
                    continue
                tool_calls += 1
                messages.append({"role": "tool", "content": result})
                continue

            raw = response.get("output")
            try:
                value = self.output_type(raw) if self.output_type else raw
                for validator in getattr(self, "validators", []):
                    validator(context, value)
            except (ValueError, ModelRetry) as failure:
                failures += 1
                if failures > self.retries:
                    raise UnexpectedModelBehavior(str(failure))
                messages.append({"role": "retry", "content": str(failure)})
                continue
            messages.append({"role": "assistant", "content": value})
            return {"output": value, "messages": messages,
                    "model_calls": model_calls, "tool_calls": tool_calls}
        raise UnexpectedModelBehavior("agent did not finish")

