class Ticket:
    def __init__(self, summary, priority):
        self.summary = summary
        self.priority = priority

    def __eq__(self, other):
        return (self.summary, self.priority) == (other.summary, other.priority)


def as_ticket(raw):
    if not isinstance(raw, dict):
        raise ValueError("expected an object with summary and priority")
    missing = [f for f in ("summary", "priority") if f not in raw]
    if missing:
        raise ValueError(f"missing field(s): {', '.join(missing)}")
    if not isinstance(raw["priority"], int) or isinstance(raw["priority"], bool):
        raise ValueError("priority must be an integer")
    if not 1 <= raw["priority"] <= 5:
        raise ValueError("priority must be between 1 and 5")
    return Ticket(raw["summary"], raw["priority"])


triage = Agent(instructions="Triage the message.", output_type=as_ticket, retries=2)

# The headline: what comes back is the validated object, not a string to parse.
run = triage.run("locked out", lambda messages, tools: {
    "output": {"summary": "Cannot log in", "priority": 4}})
assert isinstance(run["output"], Ticket), run
assert run["output"].priority + 1 == 5
assert run["model_calls"] == 1, run

# A response that fails validation is not raised at the caller: the ERROR TEXT is
# fed back to the model, which then gets it right.
attempts = []


def flaky(messages, tools):
    attempts.append(len(messages))
    if len(attempts) == 1:
        return {"output": {"summary": "Cannot log in"}}
    if len(attempts) == 2:
        return {"output": {"summary": "Cannot log in", "priority": 9}}
    return {"output": {"summary": "Cannot log in", "priority": 4}}


run = triage.run("locked out", flaky)
assert run["output"] == Ticket("Cannot log in", 4), run["output"]
assert run["model_calls"] == 3, run
feedback = [m["content"] for m in run["messages"] if m["role"] == "retry"]
assert feedback == ["missing field(s): priority",
                    "priority must be between 1 and 5"], feedback

# ...but the feedback loop is bounded, because every retry is another model call.
stubborn = Agent(output_type=as_ticket, retries=1)
try:
    stubborn.run("x", lambda m, t: {"output": {"summary": "s", "priority": 99}})
except UnexpectedModelBehavior:
    pass
else:
    raise AssertionError("retries must be bounded")

# With no declared output shape you simply get what the model produced.
assert Agent().run("hi", lambda m, t: {"output": "plain text"})["output"] == "plain text"


# Tools: the schema comes from the signature and the docstring, and the injected
# dependencies arrive through the run context rather than being hard-coded.
class Deps:
    def __init__(self, rates):
        self.rates = rates


fx = Agent(instructions="Convert currency.")


@fx.tool
def convert(ctx, amount: float, to: str) -> str:
    """Convert an amount of USD into another currency."""
    return f"{amount * ctx.deps.rates[to]:.2f} {to}"


@fx.tool_plain
def today() -> str:
    """Return today's date."""
    return "2026-01-01"


entries = {e["name"]: e for e in fx.catalog()}
assert entries["convert"]["parameters"] == {"amount": float, "to": str}, entries
assert "ctx" not in entries["convert"]["parameters"], entries
assert entries["convert"]["description"] == \
    "Convert an amount of USD into another currency."
assert entries["today"]["parameters"] == {}, entries


def scripted(messages, tools):
    assert any(t["name"] == "convert" for t in tools), tools
    if not any(m["role"] == "tool" for m in messages):
        return {"tool": "convert", "args": {"amount": 100.0, "to": "EUR"}}
    return {"output": f"That's {messages[-1]['content']}."}


run = fx.run("100 USD in EUR", scripted, deps=Deps({"EUR": 0.92}))
assert run["output"] == "That's 92.00 EUR.", run
assert run["tool_calls"] == 1 and run["model_calls"] == 2, run

# The model's arguments are validated against the signature before the function is
# ever entered, and a mistake comes back as feedback the model can act on.
calls = []


def sloppy(messages, tools):
    calls.append(1)
    if len(calls) == 1:
        return {"tool": "convert", "args": {"amount": "one hundred", "to": "EUR"}}
    if len(calls) == 2:
        return {"tool": "convert", "args": {"amount": 100.0}}
    if len(calls) == 3:
        return {"tool": "convert", "args": {"amount": 100.0, "to": "EUR"}}
    return {"output": messages[-1]["content"]}


forgiving = Agent(retries=5)
forgiving.tools = fx.tools
run = forgiving.run("q", sloppy, deps=Deps({"EUR": 0.92}))
assert run["output"] == "92.00 EUR", run
retries = [m["content"] for m in run["messages"] if m["role"] == "retry"]
assert retries == ["convert.amount must be float, got str",
                   "convert is missing argument(s): to"], retries
assert run["tool_calls"] == 1, run

# A tool may itself decide the model was wrong and send it back with a reason.
picky = Agent(retries=3)


@picky.tool
def lookup(ctx, order_id: str) -> str:
    """Look up an order."""
    if not order_id.startswith("A"):
        raise ModelRetry("order ids start with 'A'")
    return f"order {order_id} found"


def guessing(messages, tools):
    if not any(m["role"] == "tool" for m in messages):
        if not any(m["role"] == "retry" for m in messages):
            return {"tool": "lookup", "args": {"order_id": "123"}}
        return {"tool": "lookup", "args": {"order_id": "A123"}}
    return {"output": messages[-1]["content"]}


run = picky.run("find my order", guessing)
assert run["output"] == "order A123 found", run
assert [m["content"] for m in run["messages"] if m["role"] == "retry"] == \
    ["order ids start with 'A'"], run["messages"]

# A business rule that the schema cannot express runs after validation and can also
# send the model back.
strict = Agent(output_type=as_ticket, retries=2)


@strict.output_validator
def not_shouting(ctx, ticket):
    if ticket.summary.isupper():
        raise ModelRetry("write the summary in sentence case")


shouty = [{"summary": "HELP ME", "priority": 3},
          {"summary": "Help me", "priority": 3}]
run = strict.run("x", lambda m, t: {"output": shouty[min(len(
    [q for q in m if q["role"] == "retry"]), 1)]})
assert run["output"] == Ticket("Help me", 3), run["output"]
assert run["model_calls"] == 2, run

# One agent, defined once, is reused across runs with different dependencies.
first = fx.run("a", scripted, deps=Deps({"EUR": 0.5}))
second = fx.run("b", scripted, deps=Deps({"EUR": 2.0}))
assert first["output"] == "That's 50.00 EUR." and second["output"] == "That's 200.00 EUR."
